<template>
	<!--
	  Riwayat aktivitas (Field/Desk Collection) sebagai kartu collapsible —
	  pola yang sama dengan list unit di Request AYDA (AydaUnitCards). Tabel
	  terlalu sempit untuk layar ponsel: kolomnya banyak dan harus digeser
	  horizontal. Satu aktivitas = satu kartu; header memuat ringkasan, isi
	  lengkapnya muncul saat kartu dibuka.
	-->
	<div class="space-y-3">
		<div
			v-if="!rows.length"
			class="rounded-2xl border border-dashed border-ui-line-gray-300 bg-ui-surface-gray-50 px-4 py-8 text-center"
		>
			<p class="text-sm text-ui-ink-gray-400">{{ emptyText }}</p>
		</div>

		<div
			v-for="(row, idx) in rows"
			:key="row.name || idx"
			class="overflow-hidden rounded-2xl border border-ui-line-gray-200 bg-ui-surface shadow-sm"
		>
			<!-- Header kartu (klik untuk buka/tutup) -->
			<button
				type="button"
				class="flex w-full items-center gap-3 px-4 py-3 text-left transition hover:bg-ui-surface-gray-50"
				@click="toggle(idx)"
			>
				<span
					class="flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-primary/10 text-sm font-bold text-primary"
				>
					{{ idx + 1 }}
				</span>
				<span class="min-w-0 flex-1">
					<span class="block truncate text-sm font-semibold text-ui-ink-gray-900">
						{{ judul(row) }}
					</span>
					<span class="block truncate text-xs text-ui-ink-gray-400">
						{{ subjudul(row) }}
					</span>
				</span>
				<svg
					xmlns="http://www.w3.org/2000/svg"
					viewBox="0 0 24 24"
					class="h-5 w-5 shrink-0 text-ui-ink-gray-400 transition-transform"
					:class="{ 'rotate-180': isOpen(idx) }"
					fill="none"
					stroke="currentColor"
					stroke-width="2"
					stroke-linecap="round"
					stroke-linejoin="round"
				>
					<path d="m6 9 6 6 6-6" />
				</svg>
			</button>

			<!-- Isi kartu: label + nilai, urutan mengikuti `fields` -->
			<div v-if="isOpen(idx)" class="space-y-3 border-t border-ui-line-gray-100 px-4 py-4">
				<div v-for="f in visibleFields(row)" :key="f.key">
					<p class="mb-1 text-xs font-medium text-ui-ink-gray-500">
						{{ labelDari(f, row) }}
					</p>

					<!-- Foto: cukup namanya, fotonya muncul setelah diklik. -->
					<template v-if="f.fmt === 'image'">
						<button
							v-if="row[f.urlKey]"
							type="button"
							class="flex max-w-full items-center gap-1.5 border-0 bg-transparent p-0 text-left text-sm font-medium text-primary hover:underline"
							@click="openImage(row[f.urlKey], row[f.key] || labelDari(f, row))"
						>
							<svg
								xmlns="http://www.w3.org/2000/svg"
								viewBox="0 0 24 24"
								class="h-4 w-4 shrink-0"
								fill="none"
								stroke="currentColor"
								stroke-width="1.8"
								stroke-linecap="round"
								stroke-linejoin="round"
							>
								<rect width="18" height="18" x="3" y="3" rx="2" />
								<circle cx="9" cy="9" r="2" />
								<path d="m21 15-4.35-4.35a2 2 0 0 0-2.83 0L3 21" />
							</svg>
							<span class="min-w-0 truncate">{{ row[f.key] || 'Lihat foto' }}</span>
						</button>
						<p v-else class="text-sm text-ui-ink-gray-400">—</p>
					</template>

					<p v-else class="break-words text-sm text-ui-ink-gray-800">
						{{ tampil(f, row[f.key]) }}
					</p>
				</div>
			</div>
		</div>
	</div>
</template>

<script setup>
import { ref, watch } from 'vue'
import { openImage } from '../composables/attachmentViewer'

const props = defineProps({
	// Baris aktivitas apa adanya dari endpoint riwayat.
	rows: { type: Array, default: () => [] },
	// [{ key, label, fmt?, urlKey? }] — sama seperti definisi kolom tabel.
	fields: { type: Array, default: () => [] },
	// Judul kartu (baris atas header).
	titleKey: { type: String, default: 'nama_nasabah' },
	// Isi baris kedua header, digabung dengan " · " dan melewati yang kosong.
	subtitleKeys: { type: Array, default: () => [] },
	emptyText: { type: String, default: 'Belum ada riwayat.' },
	// Formatter nilai dari halaman pemanggil (fmt: date/money/check).
	format: { type: Function, required: true },
})

// Kartu yang terbuka disimpan per nama dokumen, bukan indeks, supaya tidak
// meleset kalau riwayatnya di-refresh setelah input aktivitas baru.
const openSet = ref(new Set())
function keyOf(idx) {
	return props.rows[idx]?.name ?? idx
}
function isOpen(idx) {
	return openSet.value.has(keyOf(idx))
}
function toggle(idx) {
	const s = new Set(openSet.value)
	const k = keyOf(idx)
	s.has(k) ? s.delete(k) : s.add(k)
	openSet.value = s
}
watch(
	() => props.rows,
	() => {
		openSet.value = new Set()
	}
)

function tampil(f, val) {
	return props.format(f, val)
}

// Label boleh berupa fungsi, sama seperti `showWhen`, supaya field yang isinya
// berpindah-pindah doctype (Dynamic Link "Dokumen") bisa menyebut jenisnya
// sendiri — "Resi", "TTS", atau "BSTK" — bukan sekadar "Dokumen".
function labelDari(f, row) {
	return typeof f.label === 'function' ? f.label(row) : f.label
}

// Beberapa DocField hanya tampil bila kondisi `depends_on`-nya terpenuhi.
// Halaman pemanggil menerjemahkan properti Desk tersebut menjadi `showWhen`
// supaya kartu tidak menampilkan field yang di Desk sedang tersembunyi.
function visibleFields(row) {
	return props.fields.filter((field) => !field.showWhen || field.showWhen(row))
}

function fieldOf(key) {
	return props.fields.find((f) => f.key === key)
}

function judul(row) {
	const f = fieldOf(props.titleKey)
	const val = row[props.titleKey]
	if (val == null || val === '') return '—'
	return f ? props.format(f, val) : String(val)
}

function subjudul(row) {
	return (
		props.subtitleKeys
			.map((k) => {
				const val = row[k]
				if (val == null || val === '') return ''
				const f = fieldOf(k)
				return f ? props.format(f, val) : String(val)
			})
			.filter(Boolean)
			.join(' · ') || '—'
	)
}
</script>
