<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { call, createResource, toast } from 'frappe-ui'
import { refreshCsrfToken } from '../data/session'
import { currentUser } from '../data/user'
import { openAttachment, openPdf } from '../composables/pdfViewer'
import ResiHasilDialog from '../components/ResiHasilDialog.vue'
import { popupGagalResi, popupHasilResi } from '../data/resiHasil'
import RiwayatAktivitasCards from '../components/RiwayatAktivitasCards.vue'
import { notifySuccess, notifyError } from '../composables/toast'
import SelectMenu from '../components/SelectMenu.vue'
import FotoBstkCollapse from '../components/FotoBstkCollapse.vue'

const route = useRoute()
const name = computed(() => String(route.params.name || ''))

// Kembali ke list dengan mempertahankan filter status bila ada (?status=).
const backTo = computed(() => ({
	name: route.query.from === 'PekerjaanSaya' ? 'PekerjaanSaya' : route.query.from === 'MonitoringKunjungan' ? 'MonitoringKunjungan' : 'TargetRealisasi',
	query: route.query.from ? undefined : route.query.status ? { status: route.query.status } : undefined,
}))

// ===== Input Aktivitas (Field / Desk Collection) =====
// Tombol muncul sesuai role: Field Coll → Field; Desk Coll → Desk. Admin keduanya.
const isAdmin = computed(
	() =>
		currentUser.user === 'Administrator' ||
		(currentUser.roles || []).includes('System Manager')
)
const canFieldColl = computed(
	() => isAdmin.value || (currentUser.roles || []).includes('Field Coll')
)
const canDeskColl = computed(
	() => isAdmin.value || (currentUser.roles || []).includes('Desk Coll')
)

// ===== Ubah PIC Collector (khusus Head Field Coll) =====
// Aturannya sama dengan desk: role ini boleh menyunting Target dan Realisasi,
// tetapi TERBATAS pada kolom PIC Collector — di server pun ditolak kalau kolom
// lain ikut berubah (lihat _guard_pic_only_edit di controller doctype).
const PIC_FIELD = 'pic_collector'
const canEditPic = computed(
	() => isAdmin.value || (currentUser.roles || []).includes('Head Field Coll')
)
const editMode = ref(false)
const picDraft = ref('')
const picOptions = ref([])
const picSaving = ref(false)
const picError = ref('')

async function loadPicOptions() {
	if (picOptions.value.length) return
	try {
		picOptions.value =
			(await call('juragan.api.portal.target_realisasi.get_pic_collector_options')) || []
	} catch (e) {
		picOptions.value = []
	}
}

function enterEditMode() {
	if (!canEditPic.value) return
	picError.value = ''
	picDraft.value = doc.value?.[PIC_FIELD] || ''
	editMode.value = true
	activeTab.value = 'data' // field yang bisa diubah ada di tab Data
	loadPicOptions()
}

function cancelEdit() {
	editMode.value = false
	picError.value = ''
	picDraft.value = doc.value?.[PIC_FIELD] || ''
}

async function savePicCollector() {
	if (picSaving.value) return
	const nilai = (picDraft.value || '').trim()
	if (!nilai) {
		picError.value = 'PIC Collector wajib diisi.'
		return
	}
	if (nilai === (doc.value?.[PIC_FIELD] || '')) {
		editMode.value = false
		return
	}
	picSaving.value = true
	picError.value = ''
	try {
		await call('juragan.api.portal.target_realisasi.update_pic_collector', {
			name: name.value,
			pic_collector: nilai,
		})
		if (doc.value) doc.value = { ...doc.value, [PIC_FIELD]: nilai }
		editMode.value = false
		autoToast('success', 'PIC Collector diperbarui.')
	} catch (e) {
		picError.value = e?.messages?.join('\n') || e?.message || 'Gagal menyimpan PIC Collector.'
	} finally {
		picSaving.value = false
	}
}

// Action bar tampil bila ada tombol aksi ATAU sedang mode edit (Head Field Coll
// belum tentu punya role Field/Desk Coll, jadi tombol Simpan harus tetap ada).
const showActionBar = computed(
	() =>
		!!doc.value &&
		(editMode.value || canFieldColl.value || canDeskColl.value || canViewSppuPdf.value)
)

// Toast frappe-ui tak auto-dismiss di webview → hapus manual.
function autoToast(type, message) {
	const id = toast[type](message)
	setTimeout(() => toast.remove(id), 3500)
}

const aktivitasOpen = ref(false)
const aktivitasJenis = ref('') // 'field' | 'desk'
const aktivitasSubmitting = ref(false)
const aktivitasError = ref('')
const opts = reactive({ status: [], action: [], child: [] })

// Opsi "Hasil" & "Tipe Pembayaran" — sama persis dgn Select di dialog desk.
const HASIL_OPTIONS = ['Janji Bayar', 'Pembayaran Angsuran', 'Tarik Unit', 'Kunjungan Ulang']
const TIPE_PEMBAYARAN_OPTIONS = ['TTS', 'Transfer']
const KATEGORI_BSTK_OPTIONS = ['Janji Tebus', 'Tarik Putus']

function blankAktForm() {
	return {
		tanggal_kunjungan: '',
		detail_case: '',
		hasil: '',
		tipe_pembayaran: '',
		document: '',
		nominal_bayar: '',
		nama_pic: '',
		kunci: 0,
		stnk: 0,
		keterangan_stnk: '',
		kategori: '',
		tanggal_janji_tebus: '',
		foto_bstk: [],
		status_nasabah: '',
		case_category: '',
		action: '',
		status_telpon: '',
		telpon_by: '',
		tanggal_janji_bayar: '',
	}
}
const form = reactive(blankAktForm())

// DocType tujuan field "document", diturunkan dari hasil/tipe pembayaran.
// Deterministik & identik dgn desk: Tarik Unit → BSTK, Angsuran + TTS → TTS.
const documentDoctype = computed(() => {
	if (form.hasil === 'Tarik Unit') return 'BSTK'
	if (form.hasil === 'Pembayaran Angsuran' && form.tipe_pembayaran === 'TTS') return 'TTS'
	return ''
})
const dokumenOptions = ref([])
const dokumenLoading = ref(false)

// Upload Resi hanya muncul pada Pembayaran Angsuran via Transfer. Bukti yang
// diunggah dibuat server menjadi dokumen Resi lalu ditautkan ke aktivitas.
// Berlaku untuk KSP maupun JG: sumber kontrak diteruskan ke Resi, yang lalu
// memakai master nasabah sesuai sumber itu.
const perluUploadResi = computed(
	() => form.hasil === 'Pembayaran Angsuran' && form.tipe_pembayaran === 'Transfer'
)
const resiLabel = computed(() => {
	if (resiUploading.value) return 'Mengunggah…'
	return resiNama.value || 'Pilih bukti transfer (JPG/PNG, maks 3 MB)'
})

// Nama PIC Tarikan hanya diminta untuk BSTK berreksekutor eksternal; BSTK
// internal memakai PIC dari registrasinya sendiri (lihat close_bstk).
const perluNamaPic = computed(() => {
	if (documentDoctype.value !== 'BSTK' || !form.document) return false
	const opt = dokumenOptions.value.find((o) => (o?.value ?? o) === form.document)
	return !!opt && opt.eksekutor !== 'Internal'
})

function resetBstkCloseFields() {
	form.kunci = 0
	form.stnk = 0
	form.keterangan_stnk = ''
	form.kategori = ''
	form.tanggal_janji_tebus = ''
	form.foto_bstk = []
}

function toggleBstkFlag(key) {
	form[key] = form[key] ? 0 : 1
	if (key === 'stnk' && form.stnk) form.keterangan_stnk = ''
}

// Setiap perubahan Hasil membatalkan dokumen yang dipilih pada konteks lama.
watch(
	() => form.hasil,
	(v) => {
		form.document = ''
		form.nominal_bayar = ''
		form.nama_pic = ''
		resetBstkCloseFields()
		if (v !== 'Pembayaran Angsuran' && form.tipe_pembayaran) form.tipe_pembayaran = ''
		if (v !== 'Janji Bayar') form.tanggal_janji_bayar = ''
	}
)

// Muat daftar dokumen setiap kali doctype tujuan berubah; kosongkan pilihan lama.
watch(documentDoctype, async (dt) => {
	form.document = ''
	form.nominal_bayar = ''
	form.nama_pic = ''
	dokumenOptions.value = []
	if (!dt) return
	dokumenLoading.value = true
	try {
		const r = await call('juragan.api.portal.target_realisasi.get_dokumen_options', {
			hasil: form.hasil,
			tipe_pembayaran: form.tipe_pembayaran,
		})
		dokumenOptions.value = r?.options || []
	} catch (e) {
		dokumenOptions.value = []
	} finally {
		dokumenLoading.value = false
	}
})

// Pindah tipe pembayaran membatalkan bukti transfer yang terlanjur dipilih
// (termasuk saat Hasil berubah, yang ikut mengosongkan tipe pembayaran).
watch(
	() => form.tipe_pembayaran,
	() => {
		resiUrl.value = ''
		resiNama.value = ''
	}
)

watch(
	() => form.document,
	() => resetBstkCloseFields()
)

const fotoInput = ref(null)
const fotoFile = ref(null)
const fotoName = computed(() => fotoFile.value?.name || '')

// Foto TTS: wajib saat Pembayaran Angsuran via TTS; foto dari TTS lain tidak
// boleh terbawa, jadi dikosongkan setiap dokumen/doctype tujuan berganti.
const fotoTtsInput = ref(null)
const fotoTtsFile = ref(null)
watch([documentDoctype, () => form.document], () => {
	fotoTtsFile.value = null
})
function pickFotoTts() {
	fotoTtsInput.value?.click()
}
function onFotoTts(e) {
	const f = e.target.files?.[0]
	e.target.value = ''
	if (!f) return
