// Yang disimpan di sini hanya URL gambar yang sudah terunggah. Pembuatan
// dokumen Resi dan ekstraksinya dikerjakan server SAAT AKTIVITAS DISIMPAN —
// bukan saat berkas dipilih — supaya bukti yang ditolak (rekening salah atau
// duplikat) bisa menahan penyimpanan dan mengembalikan user ke form ini.
const resiUrl = ref('')
const resiNama = ref('')
const resiUploading = ref(false)
// Hasil bacaan ditampilkan sebagai dialog, bukan hanya label di bawah tombol:
// status Duplikat / Gagal menentukan bukti transfernya dipakai atau tidak, dan
// di desk pun ini muncul sebagai dialog (frappe.msgprint di extractor).
const resiPopup = ref(null)

// Sebelumnya berkas hanya bisa DIGANTI dengan memilih ulang; tanpa ini tidak
