async function onResi(e) {
	const f = e.target.files?.[0]
	e.target.value = ''
	if (!f) return
	if (f.size > 3 * 1024 * 1024) {
		aktivitasError.value = 'Ukuran bukti transfer maksimal 3 MB.'
		return
	}

	aktivitasError.value = ''
	resiPopup.value = null
	resiUrl.value = ''
	resiNama.value = ''
	resiUploading.value = true
	try {
		resiUrl.value = await uploadRawFile(f)
		resiNama.value = f.name
	} catch (err) {
		const pesan = err?.messages?.[0] || err?.message || 'Gagal mengunggah bukti transfer.'
		aktivitasError.value = pesan
		resiPopup.value = popupGagalResi(pesan)
	} finally {
		resiUploading.value = false
	}
}
// Foto kunjungan baru diunggah saat Simpan, jauh setelah dipilih. File dari
// picker/kamera Android hanya rujukan ke berkas di disk; bila berkas itu
// berubah/hilang sebelum Simpan (mis. setelah 8x buka kamera untuk foto BSTK)
// WebView menggagalkan upload dengan "Failed to fetch". Salin isinya ke memori
// saat dipilih supaya upload tidak lagi bergantung pada berkas aslinya.
async function onFoto(e) {
	const f = e.target.files?.[0]
	e.target.value = ''
	if (!f) return
	if (f.size > 3 * 1024 * 1024) {
		aktivitasError.value = 'Ukuran foto maksimal 3 MB.'
		fotoFile.value = null
		return
	}
	try {
		const buf = await f.arrayBuffer()
		fotoFile.value = new File([buf], f.name, { type: f.type || 'image/jpeg' })
		aktivitasError.value = ''
	} catch {
		fotoFile.value = null
		aktivitasError.value = 'Foto tidak dapat dibaca, silakan pilih ulang.'
	}
}
async function uploadRawFile(file) {
	const fd = new FormData()
	fd.append('file', file, file.name)
	fd.append('is_private', '1')
	const res = await fetch('/api/method/upload_file', {
		method: 'POST',
		credentials: 'include',
		headers: { Accept: 'application/json', 'X-Frappe-CSRF-Token': window.csrf_token || '' },
		body: fd,
	})
	const json = await res.json().catch(() => ({}))
	if (!res.ok) throw new Error(json?.exception || json?.message || `HTTP ${res.status}`)
	return json.message?.file_url
}

async function submitAktivitas() {
	if (aktivitasSubmitting.value) return
	aktivitasError.value = ''
	if (!form.detail_case.trim()) return (aktivitasError.value = 'Detail Case wajib diisi.')
	if (aktivitasJenis.value === 'field') {
		if (!form.tanggal_kunjungan)
			return (aktivitasError.value = 'Tanggal Kunjungan wajib diisi.')
		if (!form.hasil) return (aktivitasError.value = 'Hasil wajib dipilih.')
		if (form.hasil === 'Pembayaran Angsuran' && !form.tipe_pembayaran)
			return (aktivitasError.value = 'Tipe Pembayaran wajib dipilih.')
		if (form.hasil === 'Janji Bayar' && !form.tanggal_janji_bayar)
			return (aktivitasError.value = 'Tanggal Janji Bayar wajib diisi.')
		if (documentDoctype.value && !form.document)
			return (aktivitasError.value = `Dokumen ${documentDoctype.value} wajib dipilih.`)
		if (documentDoctype.value === 'TTS' && !(Number(form.nominal_bayar) > 0))
			return (aktivitasError.value = 'Nominal Bayar wajib diisi untuk pembayaran via TTS.')
		if (documentDoctype.value === 'TTS' && !fotoTtsFile.value)
			return (aktivitasError.value = 'Foto TTS wajib diunggah untuk pembayaran via TTS.')
		if (perluNamaPic.value && !form.nama_pic.trim())
			return (aktivitasError.value = 'Nama PIC Tarikan wajib diisi untuk BSTK eksternal.')
		if (documentDoctype.value === 'BSTK' && !form.stnk && !form.keterangan_stnk.trim())
			return (aktivitasError.value = 'Keterangan STNK wajib diisi bila STNK tidak ada.')
	}

	aktivitasSubmitting.value = true
	try {
		const payload = {
			detail_case: form.detail_case.trim(),
			tanggal_janji_bayar:
				aktivitasJenis.value !== 'field' || form.hasil === 'Janji Bayar'
					? form.tanggal_janji_bayar || null
					: null,
		}
		if (aktivitasJenis.value === 'field') {
			payload.tanggal_kunjungan = form.tanggal_kunjungan
			payload.hasil = form.hasil
			payload.tipe_pembayaran = form.tipe_pembayaran || null
			// document_doctype diturunkan ulang server-side dari hasil/tipe.
			payload.document = documentDoctype.value ? form.document : null
			payload.nominal_bayar =
				documentDoctype.value === 'TTS' ? Number(form.nominal_bayar) || 0 : 0
			payload.nama_pic =
				documentDoctype.value === 'BSTK' ? form.nama_pic.trim() || null : null
			if (documentDoctype.value === 'BSTK') {
				payload.kunci = form.kunci ? 1 : 0
				payload.stnk = form.stnk ? 1 : 0
				payload.keterangan_stnk = form.keterangan_stnk.trim() || null
				payload.kategori = form.kategori || null
				payload.tanggal_janji_tebus = form.tanggal_janji_tebus || null
				payload.foto_bstk = form.foto_bstk || []
			}
			payload.status_nasabah = form.status_nasabah || null
			payload.case_category = form.case_category || null
			payload.action = form.action || null
			if (fotoFile.value) payload.foto_kunjungan = await uploadRawFile(fotoFile.value)
			if (documentDoctype.value === 'TTS' && fotoTtsFile.value)
				payload.foto_tts = await uploadRawFile(fotoTtsFile.value)
			if (perluUploadResi.value && resiUrl.value) payload.gambar_resi = resiUrl.value
		} else {
			payload.status_telpon = form.status_telpon || null
			payload.telpon_by = form.telpon_by || null
		}
		const hasil = await call('juragan.api.portal.target_realisasi.insert_aktivitas', {
			name: name.value,
			jenis: aktivitasJenis.value,
			payload: JSON.stringify(payload),
		})
		aktivitasOpen.value = false
		riwayatRes.fetch() // riwayat aktivitas ikut ter-refresh
		autoToast('success', 'Aktivitas berhasil disimpan')
		// Hasil bacaan bukti transfer baru diketahui saat simpan, jadi dialognya
		// muncul di sini. Bukti yang DITOLAK tidak sampai ke sini — server
		// melempar error dan formnya tetap terbuka (lihat catch).
		if (hasil?.resi) resiPopup.value = popupHasilResi(hasil.resi)
	} catch (e) {
		const pesan = e?.messages?.[0] || e?.message || String(e) || 'Gagal menyimpan aktivitas.'
		aktivitasError.value = pesan
		// Form sengaja dibiarkan terbuka supaya buktinya bisa langsung diganti.
		if (perluUploadResi.value && resiUrl.value) {
			resiPopup.value = popupGagalResi(pesan, 'Bukti Transfer Ditolak')
		}
	} finally {
		aktivitasSubmitting.value = false
	}
}

