// Format tampilan diturunkan dari fieldtype meta (bukan hardcode).
function fmtFromType(ft) {
	if (ft === 'Currency') return 'money'
	if (ft === 'Date' || ft === 'Datetime') return 'date'
	if (ft === 'Check') return 'check'
	return ''
}

const CHILD_FIELDTYPES = new Set(['Table', 'Table MultiSelect'])

// Fieldtype yang bukan data (aksi/dekorasi desk) — tak punya nilai untuk
// ditampilkan, mis. tombol "Input Aktivitas" milik Field/Desk Coll.
const NON_DATA_FIELDTYPES = new Set(['Button', 'HTML', 'Heading', 'Image', 'Fold'])

// Kelompokkan field per Section/Tab Break (persis urutan form Frappe). Field
// layout (Column Break), child table, & field non-data dilewati.
const metaSections = computed(() => {
	const out = []
	let cur = { title: '', fields: [] }
	const flush = (nextTitle) => {
		if (cur.fields.length) out.push(cur)
		cur = { title: nextTitle || '', fields: [] }
	}
	for (const f of metaFields.value) {
		if (f.fieldtype === 'Section Break' || f.fieldtype === 'Tab Break') {
			flush(f.label)
			continue
		}
		if (f.fieldtype === 'Column Break') continue
		if (CHILD_FIELDTYPES.has(f.fieldtype)) continue
		if (NON_DATA_FIELDTYPES.has(f.fieldtype)) continue
		if (f.hidden) continue
		cur.fields.push({
			key: f.fieldname,
			label: f.label || f.fieldname,
			fmt: fmtFromType(f.fieldtype),
			read_only: !!f.read_only,
		})
	}
	if (cur.fields.length) out.push(cur)
	return out
})

