// Sembunyikan field kosong (nilai "—") spt form Frappe. Field 'check' tetap
// tampil walau bernilai 0 (0/1 → Tidak/Ya, bukan kosong) — tapi hanya bila
// key-nya memang dikirim, supaya field milik KSP tidak muncul sebagai "Tidak"
// pada nasabah JG. Section yang semua field-nya kosong ikut disembunyikan.
function isEmptyVal(v) {
	return v == null || v === ''
}
const visibleNasabahSections = computed(() => {
	const data = nasabah.value
	if (!data) return []
	return nasabahSections
		.map((sec) => ({
			title: sec.title,
			fields: sec.fields.filter((f) =>
				f.fmt === 'check' ? f.key in data : !isEmptyVal(data[f.key])
			),
		}))
		.filter((sec) => sec.fields.length > 0)
})

// ---- Util -----------------------------------------------------------------
function formatDate(v) {
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}

function formatMoney(v) {
	if (v == null || v === '') return '—'
	const n = Number(v)
	if (Number.isNaN(n)) return String(v)
	return `Rp ${new Intl.NumberFormat('id-ID').format(n)}`
}

function fieldDisplay(f, val) {
	if (f.fmt === 'money') return formatMoney(val)
	if (f.fmt === 'check') return val ? 'Ya' : 'Tidak'
	if (val == null || val === '') return '—'
	if (f.fmt === 'date') return formatDate(val)
	return String(val)
}

// ===== Request SPPU (persis flow doctype Target dan Realisasi di Frappe) =====
// Kondisi tampil tombol (sama seperti setup_sppu_action di Frappe):
//   - dokumen sudah ada (detail selalu existing),
//   - `link` kosong (belum ter-approve/terhubung SPPU),
//   - `status_surat_sppu` kosong (belum pernah request),
//   - sumber BUKAN "JG" (sumber JG tidak memakai alur Request SPPU),
//   - user punya role Field Coll (Administrator/System Manager ikut, via canFieldColl).
// Aksi memanggil method whitelisted yang SAMA dengan Desk → membuat SPPU Collector
// (status "Request"), set status_surat_sppu = "Request", kirim notifikasi WA.
const canRequestSppu = computed(() => {
	const d = doc.value
	return !!(d && !d.link && !d.status_surat_sppu && d.sumber !== 'JG' && canFieldColl.value)
})
const showSppuConfirm = ref(false)
const sppuLoading = ref(false)

async function submitRequestSppu() {
	if (sppuLoading.value) return
	sppuLoading.value = true
	try {
		const sppuName = await call(
			'juragan.collection.doctype.target_dan_realisasi.target_dan_realisasi.request_sppu',
			{
				no_perjanjian: doc.value.no_perjanjian,
				nama_nasabah: doc.value.nama_nasabah,
			}
		)
		showSppuConfirm.value = false
		notifySuccess(`Request SPPU berhasil dibuat: ${sppuName}`, 'Berhasil')
		// Muat ulang → status_surat_sppu jadi "Request" → tombol otomatis hilang.
		docRes.fetch()
	} catch (e) {
		notifyError(e, 'Request SPPU gagal dibuat')
	} finally {
		sppuLoading.value = false
	}
}

// ===== Lihat PDF SPPU (persis setup_pdf_button Frappe) =====
// Muncul bila ADA SPPU Collector berstatus "Approved" untuk no_perjanjian ini.
// (Tanpa gate role — sama seperti Frappe.) Buka print format "Format SPPU KSP"
// di PDF viewer in-app yang sudah ada.
const approvedSppuName = ref('')
const canViewSppuPdf = computed(() => !!approvedSppuName.value)

async function loadApprovedSppu() {
	approvedSppuName.value = ''
	const np = doc.value?.no_perjanjian
	if (!np) return
	try {
		const res = await call('frappe.client.get_value', {
			doctype: 'SPPU Collector',
			filters: { no_perjanjian: np, status: 'Approved' },
			fieldname: 'name',
		})
		approvedSppuName.value = res?.name || ''
	} catch (e) {
		approvedSppuName.value = ''
	}
}

function openSppuPdf() {
	if (!approvedSppuName.value) return
	const url =
		`/api/method/frappe.utils.print_format.download_pdf` +
		`?doctype=${encodeURIComponent('SPPU Collector')}` +
		`&name=${encodeURIComponent(approvedSppuName.value)}` +
		`&format=${encodeURIComponent('Format SPPU KSP')}` +
		`&no_letterhead=0&_lang=id`
	openPdf(url, `SPPU ${approvedSppuName.value}`)
}

// ---- Tab sticky (offset = tinggi header), pola sama dgn Data Pengajuan --------
const headerRef = ref(null)
const tabStripRef = ref(null)
const tabTop = ref(0)
function measureSticky() {
	const h = headerRef.value?.offsetHeight || 0
	// Overlap 1px → tidak ada celah rambut akibat pembulatan sub-pixel.
	tabTop.value = Math.max(0, h - 1)
}
let _stickyRO = null
function setupStickyObservers() {
	if (typeof ResizeObserver === 'undefined' || _stickyRO) return
	_stickyRO = new ResizeObserver(() => measureSticky())
	if (headerRef.value) _stickyRO.observe(headerRef.value)
	if (tabStripRef.value) _stickyRO.observe(tabStripRef.value)
}
watch(activeTab, () => nextTick(measureSticky))
onBeforeUnmount(() => {
	_stickyRO?.disconnect()
	window.removeEventListener('resize', measureSticky)
})

function statusPillClass(status) {
	switch (status) {
		case 'GAGAL BAYAR':
			return 'bg-ui-surface-red-50 text-ui-ink-red-600'
		case 'PARTIAL':
			return 'bg-ui-surface-orange-50 text-ui-ink-orange-600'
		case 'TARIKAN':
			return 'bg-ui-surface-pink-50 text-ui-ink-pink-600'
		case 'DONE':
			return 'bg-ui-surface-blue-50 text-ui-ink-blue-600'
		case 'BELUM JTO':
			return 'bg-ui-surface-cyan-50 text-ui-ink-cyan-600'
		default:
			return 'bg-ui-surface-gray-100 text-ui-ink-gray-600'
	}
}

